function Hero() {
    return (
        
      <div className="flex flex-col items-center justify-center h-screen bg-gray-100">
        <h1 className="myName">MARK EVRO</h1>
        <p> I'm a Math & CS student at UBC, interested in full-stack SWE and research. 
                        Currently, most of my time is spent doing research at UBC's visual Cognition Lab (NOVA Project),
                        and helping build/maintain UBC's Science Undergraduate Society's website. 
                        A more comprehensive view of my work can be seen below/on my GitHub! </p> 
      </div>
    );
  }
  
export default Hero;
